create database insurance_db;
use insurance_db;

CREATE TABLE `customer_information` (
  `Customer ID` VARCHAR(1024),
  `Name` VARCHAR(1024),
  `Gender` VARCHAR(1024),
  `Age` BIGINT,
  `Occupation` VARCHAR(1024),
  `Marital Status` VARCHAR(1024),
  `Address (City, State, Zip Code)` VARCHAR(1024),
  `Age group` VARCHAR(1024)
);


select*from customer_information;

CREATE TABLE `additional_fields` (
  `Agent ID` VARCHAR(1024),
  `Renewal Status` VARCHAR(1024),
  `Policy Discounts` BIGINT,
  `Risk Score` BIGINT,
  `Policy ID` VARCHAR(1024)
);


select*from additional_fields;

CREATE TABLE `policy_details` (
  `Policy ID` VARCHAR(1024),
  `Policy Type` VARCHAR(1024),
  `Coverage Amount` BIGINT,
  `Premium Amount` DOUBLE,
  `Policy Start Date` DATETIME,
  `Policy End Date` DATETIME,
  `Payment Frequency` VARCHAR(1024),
  `Status` VARCHAR(1024),
  `Customer ID` VARCHAR(1024),
  `Policy Start date year` BIGINT,
  `Policy Start date Month` BIGINT,
  `Policy End date Year` BIGINT,
  `Policy End date Month` BIGINT
);


select*from policy_details;

CREATE TABLE `claims` (
  `Claim ID` VARCHAR(1024),
  `Date of Claim` DATETIME,
  `Claim Amount` BIGINT,
  `Claim Status` VARCHAR(1024),
  `Reason for Claim` VARCHAR(1024),
  `Settlement Date` DATETIME NULL,
  `Policy ID` VARCHAR(1024)
);



select*from claims;

CREATE TABLE `payment_history` (
  `Payment ID` VARCHAR(1024),
  `Date of Payment` DATETIME,
  `Amount Paid` DOUBLE,
  `Payment Method` VARCHAR(1024),
  `Payment Status` VARCHAR(1024),
  `Policy ID` VARCHAR(1024)
);




